insert into public.formulas (slug, name, segment_id, line, format, regulatory_product_type, pote_contents_description, net_weight, serving_description, ingredients_list, usage_instructions, benefits, general_benefits_summary, warnings, target_audience, storage_instructions, technical_sheet_title, list_price_cents, minimum_order_potes, sort_order, active, metadata, compliance_verified_at, compliance_norms, compliance_source) values (
  'diabetes-em-capsulas', 'Diabetes em Cápsulas', (select id from public.segments where slug = 'diabetes'), 'essencial', 'capsula', 'SUPLEMENTO ALIMENTAR EM CÁPSULA', '60 Cápsulas', '30 g', '1 g (2 cápsulas)',
  'Mio-inositol, antiumectante dióxido de silício (INS 551), bisglicinato de zinco, nicotinamida (vitamina B3), cloridrato de piridoxina (vitamina B6), cloridrato de tiamina (vitamina B1), picolinato de cromo e cápsula: gelatina, água purificada e corante dióxido de titânio (INS 171).',
  'Ingerir 2 cápsulas ao dia, ou conforme orientação de profissional de saúde.',
  array['O cromo auxilia no metabolismo de proteínas, carboidratos e gorduras.', 'O zinco auxilia no metabolismo de proteínas, carboidratos e gorduras.', 'A tiamina auxilia no metabolismo de proteínas, carboidratos e gorduras.', 'A niacina auxilia no metabolismo de proteínas, carboidratos e gorduras.', 'A vitamina B6 auxilia no metabolismo de proteínas, carboidratos e gorduras.', 'A vitamina B6 auxilia no metabolismo de proteínas e do glicogênio.', 'A tiamina auxilia no metabolismo energético.', 'A niacina auxilia no metabolismo energético.', 'A vitamina B6 auxilia no metabolismo energético.', 'O mio-inositol é um poliol cíclico de seis carbonos, a forma de inositol mais abundante na natureza.', 'O zinco está presente como bisglicinato, quelato em que o mineral se liga a duas moléculas de glicina.', 'A vitamina B3 está presente como nicotinamida, a amida do ácido nicotínico.', 'A vitamina B6 está presente como cloridrato de piridoxina.', 'A vitamina B1 está presente como cloridrato de tiamina.', 'O cromo está presente como picolinato de cromo, complexo de cromo trivalente com três moléculas de ácido picolínico.']::text[],
  'Fórmula em cápsulas que reúne cromo, zinco e as vitaminas B1, B3 e B6, todos em quantidade que atende ao mínimo da IN 28/2018 e com a alegação aprovada pela ANVISA de que auxiliam no metabolismo de proteínas, carboidratos e gorduras, e 900 mg de mio-inositol por dose. O cromo entra como picolinato e o zinco como bisglicinato. Destina-se a adultos, com ingestão de duas cápsulas ao dia.',
  'Este produto não é um medicamento.
Não exceder a recomendação diária de consumo indicada na embalagem.
Mantenha fora do alcance de crianças.
Público indicado: adultos (19 anos ou mais).
Ingerir 2 cápsulas ao dia.
Este produto não deve ser consumido por gestantes, lactantes e crianças.
Pessoas com enfermidades e/ou sob uso de medicamentos, consulte seu médico.
Conservar em local seco, fresco e arejado, ao abrigo da luz e do calor excessivo, em temperatura ambiente entre 15 °C e 30 °C. Após aberto, consumir em até 60 dias. Não consumir se o lacre de segurança estiver violado.',
  'Adultos (19 anos ou mais).',
  'Conservar o produto em local seco, fresco e arejado, ao abrigo da luz e do calor excessivo, em temperatura ambiente entre 15 °C e 30 °C.
Após aberto, consumir em até 60 dias.
Não consumir se o lacre de segurança estiver violado.',
  'Cromo, Zinco, Vitaminas B1, B3 e B6 e Inositol — 60 Cápsulas', null, 100, 10, false, '{"fonte": "linha_essencial_2026-09-23", "gerador": "anvisa/catalogo-lemon/novos_produtos_essencial.py", "linha": "essencial", "criado_em": "2026-09-23", "pendencias": ["tabela nutricional não calculada (depende de laudos e do RT)", "preço não definido — fórmula gravada como rascunho (active = false) até o dono passar o preço", "sem foto do pote (card mostra o ícone do formato)"]}'::jsonb,
  now(), array['IN 28/2018 (atualizada até a IN 470/2026)', 'RDC 243/2018']::text[], 'Massa bruta e ativo de cada insumo conferidos contra o painel oficial da ANVISA de 23/09/2026 (script novos_produtos_essencial.py)');
