insert into public.formula_compositions (formula_id, ingredient_name, quantity, unit, sort_order, ingredient_id, metadata) values ((select id from public.formulas where slug = 'saude-da-prostata-em-gotas'), 'Óleo de semente de abóbora', 0.99, 'ml', 0, null, '{"papel": "constituinte", "constituinte": "Lipídeos", "forma_insumo": "óleo de semente de abóbora (Cucurbita spp.)", "forma_anexo_i": "Óleo de semente de abóbora (família Curcubitaceae)", "linha_anexo": "I·Óleo de semente de abóbora (família Curcubitaceae); III/IV·Lipídeos", "limite_painel_19": "Lipídeos: Mínimo: 5 g Máximo: Não estabelecido Ácido Linoleico n-6: Mínimo: 2,55 g Máximo: 25,5 g Ácido alfa-linolênico n-3: Mínimo: 0,24 g Máximo: 2,4 g", "minimo_mg": 5000.0, "maximo_mg": null, "ativo_mg": null, "bruto_mg": null, "conta": "0,99 ml volume por dose; massa depende da densidade do lote (ficha do fornecedor)", "teor_fonte": "insumo a adquirir", "laudo_lote": null, "status": "abaixo do mínimo — decisão do dono", "insumo_a_adquirir": true, "fonte": "linha_essencial_2026-09-23", "verificado_em": "2026-09-23", "decisao_do_dono": "Decisão do dono em 23/09/2026: frasco de 30 mL, 1 mL (20 gotas) ao dia, 30 doses, sabendo que o painel pede no mínimo 5 g de lipídeos por dia. Abaixo do mínimo, sem alegação de lipídeos (FAQ ANVISA 9ª ed., respostas 49 e 56)."}'::jsonb);
insert into public.formula_compositions (formula_id, ingredient_name, quantity, unit, sort_order, ingredient_id, metadata) values ((select id from public.formulas where slug = 'saude-da-prostata-em-gotas'), 'Vitamina E', 10, 'mg', 1, '50ae4e0c-d18d-4fb6-9fc3-cee89ce37ef7', '{"papel": "constituinte", "constituinte": "Vitamina E", "forma_insumo": "D-alfa-tocoferol (vitamina E)", "forma_anexo_i": "Dextroalfatocoferol/D-alfa-tocoferol", "linha_anexo": "I·Dextroalfatocoferol/D-alfa-tocoferol; III/IV·Vitamina E", "limite_painel_19": "Mínimo: 2,25 mg Máximo: 1000 mg", "minimo_mg": 2.25, "maximo_mg": 1000.0, "ativo_mg": 10.0, "bruto_mg": 10.0, "conta": "10 mg × 1 (RRR-α-tocoferol = α-tocoferol, nota v do Anexo III da IN 28); teor 100% assumido como teto = 10 mg", "teor_fonte": "assumido", "laudo_lote": null, "status": "conforme", "insumo_a_adquirir": true, "fonte": "linha_essencial_2026-09-23", "verificado_em": "2026-09-23", "pct_do_maximo_bruto": 1.0, "pct_do_maximo_ativo": 1.0}'::jsonb);

insert into public.formulas (slug, name, segment_id, line, format, regulatory_product_type, pote_contents_description, net_weight, serving_description, ingredients_list, usage_instructions, benefits, general_benefits_summary, warnings, target_audience, storage_instructions, technical_sheet_title, list_price_cents, minimum_order_potes, sort_order, active, metadata, compliance_verified_at, compliance_norms, compliance_source) values (
  'antioxidante-em-capsulas', 'Antioxidante em Cápsulas', (select id from public.segments where slug = 'antioxidantes-e-longevidade'), 'essencial', 'capsula', 'SUPLEMENTO ALIMENTAR EM CÁPSULA', '60 Cápsulas', '30 g', '1 g (2 cápsulas)',
  'Ácido ascórbico (vitamina C), antiumectante dióxido de silício (INS 551), coenzima Q10 (ubiquinona), trans-resveratrol, acetato de DL-alfa-tocoferol (vitamina E), bisglicinato de zinco, L-selenometionina e cápsula: gelatina, água purificada e corante dióxido de titânio (INS 171).',
  'Ingerir 2 cápsulas ao dia, ou conforme orientação de profissional de saúde.',
  array['A vitamina C é um antioxidante que auxilia na proteção dos danos causados pelos radicais livres.', 'A vitamina E é um antioxidante que auxilia na proteção dos danos causados pelos radicais livres.', 'O zinco é um antioxidante que auxilia na proteção dos danos causados pelos radicais livres.', 'O selênio é um antioxidante que auxilia na proteção dos danos causados pelos radicais livres.', 'A vitamina C auxilia na regeneração da forma reduzida da vitamina E.', 'A vitamina C auxilia no funcionamento do sistema imune.', 'O zinco auxilia no funcionamento do sistema imune.', 'O selênio auxilia no funcionamento do sistema imune.', 'A vitamina C auxilia na formação do colágeno.', 'A vitamina C está presente como ácido L-ascórbico.', 'A coenzima Q10 (ubiquinona) é uma benzoquinona lipossolúvel presente nas membranas das células, em especial nas mitocôndrias.', 'O trans-resveratrol é um polifenol da classe dos estilbenos, encontrado naturalmente na casca da uva.', 'A vitamina E está presente como acetato de DL-alfa-tocoferol, forma sintética estável ao ar.', 'O zinco está presente como bisglicinato, quelato em que o mineral se liga a duas moléculas de glicina.', 'O selênio está presente como L-selenometionina, aminoácido em que o selênio ocupa o lugar do enxofre da metionina.']::text[],
  'Fórmula em cápsulas que reúne quatro nutrientes com a alegação aprovada pela ANVISA de antioxidante que auxilia na proteção dos danos causados pelos radicais livres (vitamina C, vitamina E, zinco e selênio) e dois compostos de uso consagrado em fórmulas de longevidade: 150 mg de coenzima Q10 e 100 mg de trans-resveratrol por dose. Destina-se a adultos, com ingestão de duas cápsulas ao dia.',
  'Este produto não é um medicamento.
Não exceder a recomendação diária de consumo indicada na embalagem.
Mantenha fora do alcance de crianças.
Público indicado: adultos (19 anos ou mais).
Ingerir 2 cápsulas ao dia.
Este produto não deve ser consumido por gestantes, lactantes e crianças.
