insert into public.formulas (slug, name, segment_id, line, format, regulatory_product_type, pote_contents_description, net_weight, serving_description, ingredients_list, usage_instructions, benefits, general_benefits_summary, warnings, target_audience, storage_instructions, technical_sheet_title, list_price_cents, minimum_order_potes, sort_order, active, metadata, compliance_verified_at, compliance_norms, compliance_source) values (
  'vitamina-b12-em-gotas', 'Vitamina B12 em Gotas', (select id from public.segments where slug = 'linha-de-gotas'), 'essencial', 'liquido', 'SUPLEMENTO ALIMENTAR LÍQUIDO', '30 mL', null, '1 mL (20 gotas)',
  'Água purificada, glicerina vegetal (glicerol – INS 422), conservador sorbato de potássio (INS 202), conservador benzoato de sódio (INS 211), acidulante ácido cítrico (INS 330) e metilcobalamina (vitamina B12).',
  'Ingerir 20 gotas (1 mL) ao dia, ou conforme orientação de profissional de saúde.',
  array['A vitamina B12 auxilia na formação de células vermelhas do sangue.', 'A vitamina B12 auxilia na função normal do sistema nervoso.', 'A vitamina B12 auxilia no metabolismo energético.', 'A vitamina B12 auxilia no funcionamento do sistema imune.', 'A vitamina B12 auxilia no metabolismo da homocisteína.', 'A vitamina B12 está presente como metilcobalamina, uma das formas coenzimáticas da vitamina.']::text[],
  'Vitamina B12 na forma de metilcobalamina, uma das formas coenzimáticas da vitamina, em solução aquosa. Dose de 20 gotas (1 mL) ao dia, para adultos.',
  'Este produto não é um medicamento.
Não exceder a recomendação diária de consumo indicada na embalagem.
Mantenha fora do alcance de crianças.
Público indicado: adultos (19 anos ou mais).
Ingerir 20 gotas (1 mL) ao dia.
Conservar em local seco, fresco e arejado, ao abrigo da luz e do calor excessivo, em temperatura ambiente entre 15 °C e 30 °C. Após aberto, consumir em até 60 dias. Não consumir se o lacre de segurança estiver violado.',
  'Adultos (19 anos ou mais).',
  'Conservar o produto em local seco, fresco e arejado, ao abrigo da luz e do calor excessivo, em temperatura ambiente entre 15 °C e 30 °C.
Após aberto, consumir em até 60 dias.
Não consumir se o lacre de segurança estiver violado.',
  'Vitamina B12 (Metilcobalamina) em Gotas (Frasco de 30 mL)', null, 100, 70, false, '{"fonte": "linha_essencial_2026-09-23", "gerador": "anvisa/catalogo-lemon/novos_produtos_essencial.py", "linha": "essencial", "criado_em": "2026-09-23", "pendencias": ["tabela nutricional não calculada (depende de laudos e do RT)", "preço não definido — fórmula gravada como rascunho (active = false) até o dono passar o preço", "sem foto do pote (card mostra o ícone do formato)"]}'::jsonb,
  now(), array['IN 28/2018 (atualizada até a IN 470/2026)', 'RDC 243/2018']::text[], 'Massa bruta e ativo de cada insumo conferidos contra o painel oficial da ANVISA de 23/09/2026 (script novos_produtos_essencial.py)');
insert into public.formula_compositions (formula_id, ingredient_name, quantity, unit, sort_order, ingredient_id, metadata) values ((select id from public.formulas where slug = 'vitamina-b12-em-gotas'), 'Vitamina B12', 9.0817, 'mcg', 0, '6c3d1585-a0ee-4f59-95dc-d433c81c8180', '{"papel": "constituinte", "constituinte": "Vitamina B12", "forma_insumo": "metilcobalamina (vitamina B12)", "forma_anexo_i": "Metilcobalamina", "linha_anexo": "I·Metilcobalamina; III/IV·Vitamina B12", "limite_painel_19": "Mínimo: 0,36 μg Máximo: 9,94 μg", "minimo_mg": 0.00035999999999999997, "maximo_mg": 0.00994, "ativo_mg": 0.0089999647, "bruto_mg": 0.0090817, "conta": "9,0817 mcg × 0,991 (teor base anidra) = 9 µg", "teor_fonte": "laudo", "laudo_lote": "IDNLABS lote M250321B (interno 20334) — 99,1% base anidra (val. 24/03/2028)", "status": "conforme", "insumo_a_adquirir": false, "fonte": "linha_essencial_2026-09-23", "verificado_em": "2026-09-23", "pct_do_maximo_bruto": 91.4, "pct_do_maximo_ativo": 90.5}'::jsonb);
