insert into public.formulas (slug, name, segment_id, line, format, regulatory_product_type, pote_contents_description, net_weight, serving_description, ingredients_list, usage_instructions, benefits, general_benefits_summary, warnings, target_audience, storage_instructions, technical_sheet_title, list_price_cents, minimum_order_potes, sort_order, active, metadata, compliance_verified_at, compliance_norms, compliance_source) values (
  'multivitaminico-em-gotas', 'Multivitamínico em Gotas', (select id from public.segments where slug = 'linha-de-gotas'), 'essencial', 'liquido', 'SUPLEMENTO ALIMENTAR LÍQUIDO', '30 mL', null, '1 mL (20 gotas)',
  'Água purificada, glicerina vegetal (glicerol – INS 422), ácido ascórbico (vitamina C), nicotinamida (vitamina B3), D-pantotenato de cálcio (vitamina B5), conservador sorbato de potássio (INS 202), riboflavina-5''-fosfato de sódio (vitamina B2), cloridrato de piridoxina (vitamina B6), cloridrato de tiamina (vitamina B1), acidulante ácido cítrico (INS 330), ácido fólico, D-biotina e metilcobalamina (vitamina B12).',
  'Ingerir 20 gotas (1 mL) ao dia, ou conforme orientação de profissional de saúde.',
  array['A vitamina C auxilia no funcionamento do sistema imune.', 'A vitamina C é um antioxidante que auxilia na proteção dos danos causados pelos radicais livres.', 'A tiamina auxilia no metabolismo energético.', 'A riboflavina auxilia no metabolismo energético.', 'A niacina auxilia no metabolismo energético.', 'O ácido pantotênico auxilia no metabolismo energético.', 'A vitamina B6 auxilia no metabolismo energético.', 'A biotina auxilia no metabolismo energético.', 'A vitamina B12 auxilia no metabolismo energético.', 'O ácido fólico auxilia na formação das células vermelhas do sangue.', 'A vitamina B12 auxilia na formação de células vermelhas do sangue.', 'A vitamina C está presente como ácido L-ascórbico.', 'A vitamina B3 está presente como nicotinamida, a amida do ácido nicotínico.', 'A vitamina B5 está presente como D-pantotenato de cálcio.', 'A vitamina B2 está presente como riboflavina-5''-fosfato de sódio, forma solúvel em água.', 'A vitamina B6 está presente como cloridrato de piridoxina.', 'A vitamina B1 está presente como cloridrato de tiamina.', 'O ácido fólico é a forma sintética do folato (ácido pteroil-L-glutâmico).', 'A vitamina B12 está presente como metilcobalamina, uma das formas coenzimáticas da vitamina.']::text[],
  'Solução em gotas com vitamina C e as oito vitaminas do complexo B (tiamina, riboflavina, niacina, ácido pantotênico, vitamina B6, biotina, ácido fólico e vitamina B12), todas em quantidade que atende ao mínimo da IN 28/2018. Dose de 20 gotas (1 mL) ao dia, para adultos.',
  'Este produto não é um medicamento.
Não exceder a recomendação diária de consumo indicada na embalagem.
Mantenha fora do alcance de crianças.
Público indicado: adultos (19 anos ou mais).
Ingerir 20 gotas (1 mL) ao dia.
Conservar em local seco, fresco e arejado, ao abrigo da luz e do calor excessivo, em temperatura ambiente entre 15 °C e 30 °C. Após aberto, consumir em até 60 dias. Não consumir se o lacre de segurança estiver violado.',
  'Adultos (19 anos ou mais).',
  'Conservar o produto em local seco, fresco e arejado, ao abrigo da luz e do calor excessivo, em temperatura ambiente entre 15 °C e 30 °C.
Após aberto, consumir em até 60 dias.
Não consumir se o lacre de segurança estiver violado.',
  'Vitamina C e Vitaminas do Complexo B em Gotas (Frasco de 30 mL)', null, 100, 80, false, '{"fonte": "linha_essencial_2026-09-23", "gerador": "anvisa/catalogo-lemon/novos_produtos_essencial.py", "linha": "essencial", "criado_em": "2026-09-23", "pendencias": ["tabela nutricional não calculada (depende de laudos e do RT)", "preço não definido — fórmula gravada como rascunho (active = false) até o dono passar o preço", "sem foto do pote (card mostra o ícone do formato)"]}'::jsonb,
  now(), array['IN 28/2018 (atualizada até a IN 470/2026)', 'RDC 243/2018']::text[], 'Massa bruta e ativo de cada insumo conferidos contra o painel oficial da ANVISA de 23/09/2026 (script novos_produtos_essencial.py)');
