insert into public.formulas (slug, name, segment_id, line, format, regulatory_product_type, pote_contents_description, net_weight, serving_description, ingredients_list, usage_instructions, benefits, general_benefits_summary, warnings, target_audience, storage_instructions, technical_sheet_title, list_price_cents, minimum_order_potes, sort_order, active, metadata, compliance_verified_at, compliance_norms, compliance_source) values (
  'zinco-em-gotas', 'Zinco em Gotas', (select id from public.segments where slug = 'linha-de-gotas'), 'essencial', 'liquido', 'SUPLEMENTO ALIMENTAR LÍQUIDO', '30 mL', null, '1 mL (20 gotas)',
  'Água purificada, glicerina vegetal (glicerol – INS 422), bisglicinato de zinco, conservador sorbato de potássio (INS 202), conservador benzoato de sódio (INS 211) e acidulante ácido cítrico (INS 330).',
  'Ingerir 20 gotas (1 mL) ao dia, ou conforme orientação de profissional de saúde.',
  array['O zinco auxilia no funcionamento do sistema imune.', 'O zinco é um antioxidante que auxilia na proteção dos danos causados pelos radicais livres.', 'O zinco auxilia na síntese de proteínas.', 'O zinco auxilia no processo de divisão celular.', 'O zinco contribui para a manutenção do cabelo, da pele e das unhas.', 'O zinco auxilia na manutenção de ossos.', 'O zinco está presente como bisglicinato, quelato em que o mineral se liga a duas moléculas de glicina.']::text[],
  'Zinco na forma de bisglicinato, quelato em que o mineral se liga a duas moléculas de glicina, em solução aquosa. Dose de 20 gotas (1 mL) ao dia. Produto de um mineral só, base para uma linha mineral.',
  'Este produto não é um medicamento.
Não exceder a recomendação diária de consumo indicada na embalagem.
Mantenha fora do alcance de crianças.
Público indicado: adultos (19 anos ou mais).
Ingerir 20 gotas (1 mL) ao dia.
Conservar em local seco, fresco e arejado, ao abrigo da luz e do calor excessivo, em temperatura ambiente entre 15 °C e 30 °C. Após aberto, consumir em até 60 dias. Não consumir se o lacre de segurança estiver violado.',
  'Adultos (19 anos ou mais).',
  'Conservar o produto em local seco, fresco e arejado, ao abrigo da luz e do calor excessivo, em temperatura ambiente entre 15 °C e 30 °C.
Após aberto, consumir em até 60 dias.
Não consumir se o lacre de segurança estiver violado.',
  'Zinco (Bisglicinato) em Gotas (Frasco de 30 mL)', null, 100, 90, false, '{"fonte": "linha_essencial_2026-09-23", "gerador": "anvisa/catalogo-lemon/novos_produtos_essencial.py", "linha": "essencial", "criado_em": "2026-09-23", "pendencias": ["tabela nutricional não calculada (depende de laudos e do RT)", "preço não definido — fórmula gravada como rascunho (active = false) até o dono passar o preço", "sem foto do pote (card mostra o ícone do formato)"]}'::jsonb,
  now(), array['IN 28/2018 (atualizada até a IN 470/2026)', 'RDC 243/2018']::text[], 'Massa bruta e ativo de cada insumo conferidos contra o painel oficial da ANVISA de 23/09/2026 (script novos_produtos_essencial.py)');
